"""Shared fixtures. Generated by `eos scaffold tests-python`; edit freely.
Integration tests use a real Postgres in Docker (testcontainers), never mocks of your own DB.
Mark them `@pytest.mark.integration`; they skip when Docker is not available.
Dev deps: uv add --dev pytest pytest-cov "testcontainers[postgres]"
"""

import datetime
import json
import os
import shutil
from pathlib import Path

import pytest

try:  # property-based tests: `pytest --hypothesis-profile=nightly` for a long run (CI uses the built-in "ci")
    from hypothesis import settings

    settings.register_profile("nightly", max_examples=2000)
except ImportError:
    pass


def _docker_available() -> bool:
    return bool(os.environ.get("DOCKER_HOST")) or shutil.which("docker") is not None


@pytest.fixture(scope="session")
def postgres_url():
    if not _docker_available():
        pytest.skip("Docker not available: integration test skipped")
    from testcontainers.postgres import PostgresContainer

    with PostgresContainer("postgres:{{PG_TAG}}") as pg:
        yield pg.get_connection_url()


def _quarantined() -> dict[str, dict]:
    """Active entries of tests/quarantine.json (`eos quarantine add`). Expired entries are ignored here, so the
    test fails again, and `eos check` fails CI until someone fixes or deletes it."""
    today = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
    for d in [Path(__file__).parent, *Path(__file__).parents]:
        f = d / "quarantine.json" if d == Path(__file__).parent else d / "tests" / "quarantine.json"
        if f.is_file():
            entries = json.loads(f.read_text(encoding="utf-8")).get("tests", [])
            return {e["id"]: e for e in entries if str(e.get("expires", "")) >= today}
    return {}


def pytest_collection_modifyitems(config, items):
    quarantine = _quarantined()
    for item in items:
        if "postgres_url" in getattr(item, "fixturenames", ()):
            item.add_marker(pytest.mark.integration)
        entry = quarantine.get(item.nodeid) or next(
            (e for k, e in quarantine.items() if item.nodeid.endswith("/" + k) or k.endswith("/" + item.nodeid)), None
        )
        if entry:  # still runs and reports, but cannot fail the build (pytest's "manual quarantine")
            reason = f"quarantined until {entry['expires']}: {entry['reason']} ({entry['issue']})"
            item.add_marker(pytest.mark.xfail(strict=False, reason=reason))
